// GET /api/preview/cronograma/:token — PÚBLICO, genera la vista de cronograma de curso
export const getCourseSchedulePreview = async (req: Request, res: Response): Promise<void> => {
  try {
    const { token } = req.params;
    const bypassToken = req.query.token as string | undefined;
    console.log('[getCourseSchedulePreview] Incoming Request:', {
      params: req.params,
      query: req.query,
    });

    const preview = await previewRepo().findOne({ where: { token } });
    if (!preview) {
      res.status(404).send(errorPage('🔍 Cronograma no encontrado', 'El enlace de cronograma solicitado no existe.'));
      return;
    }

    const course = await courseRepo().findOne({ where: { id: preview.courseId } });
    const rows = await rowRepo().find({
      where: { courseId: preview.courseId },
      order: { sortOrder: 'ASC' },
    });

    const roleParam = (req.query.rol || req.query.role || '') as string;
    const cleanRole = roleParam.toLowerCase().trim();
    const isTeacherRole = ['teacher', 'editingteacher', 'admin', 'manager', 'docente', 'coordinador', 'tutor'].includes(cleanRole);
    let isTeacherBypass = (bypassToken === getCourseBypassToken(preview.token)) || isTeacherRole;

    const alumnoId = req.query.alumnoId as string | undefined;
    const alumnoNombre = req.query.alumnoNombre as string | undefined;

    if (!isTeacherBypass && alumnoId && course && course.moodleCourseId) {
      const cacheKey = `${course.moodleCourseId}-${alumnoId}`;
      const cached = moodleRoleCache.get(cacheKey);
      const now = Date.now();
      
      if (cached && cached.expires > now) {
        isTeacherBypass = cached.isTeacher;
      } else {
        const userRoles = await checkMoodleUserRole(course.moodleCourseId, alumnoId);
        const hasTeacherRole = userRoles.some(r => 
          ['teacher', 'editingteacher', 'admin', 'manager', 'editing_teacher', 'docente', 'coordinador', 'tutor'].includes(r)
        );
        isTeacherBypass = hasTeacherRole;
        moodleRoleCache.set(cacheKey, {
          isTeacher: hasTeacherRole,
          expires: now + 60 * 60 * 1000
        });
      }
    }

    const courseName = course?.name || preview.courseName;

    const groupMap = new Map<string, { name: string; moduloNumero: string | null; rows: CourseRow[] }>();
    const groupOrder: string[] = [];

    for (const row of rows) {
      const key = row.modulo || 'Sin clase';
      if (!groupMap.has(key)) {
        groupMap.set(key, { name: key, moduloNumero: row.moduloNumero, rows: [] });
        groupOrder.push(key);
      }
      groupMap.get(key)!.rows.push(row);
    }

    const classGroups = groupOrder.map(k => groupMap.get(k)!);
    classGroups.sort((a, b) => {
      const numA = parseInt(a.moduloNumero || '', 10);
      const numB = parseInt(b.moduloNumero || '', 10);
      const hasA = !isNaN(numA);
      const hasB = !isNaN(numB);
      if (hasA && hasB) return numA - numB;
      if (hasA && !hasB) return -1;
      if (!hasA && hasB) return 1;
      return (a.name || '').localeCompare(b.name || '');
    });

    const subjects = [...new Set(rows.map(r => r.materia).filter(m => m && m.trim()))];

    let dbOpenedIds: string[] = [];
    if (alumnoId) {
      try {
        const progressRepo = AppDataSource.getRepository(StudentResourceProgress);
        const progressList = await progressRepo.find({
          where: { alumnoMoodleId: alumnoId, courseId: preview.courseId }
        });
        dbOpenedIds = progressList.map(p => p.rowId);
      } catch (err) {
        console.error('Error fetching student resource progress from DB:', err);
      }
    }

    const html = await buildScheduleHtml(
      courseName,
      classGroups,
      subjects,
      isTeacherBypass,
      preview.token,
      preview.courseId,
      dbOpenedIds,
      alumnoId,
      alumnoNombre
    );

    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate, max-age=0');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
    res.setHeader('Surrogate-Control', 'no-store');
    res.setHeader('Vary', '*');
    res.send(html);
  } catch (error) {
    console.error('[preview] Error al obtener cronograma:', error);
    res.status(500).send(errorPage('❌ Error interno', 'Ocurrió un error al cargar el cronograma.'));
  }
};

export const getCourseBypass = async (req: Request, res: Response): Promise<void> => {
  try {
    const { token } = req.params;
    const preview = await previewRepo().findOne({ where: { token } });
    if (!preview) {
      res.status(404).json({ error: 'Cronograma no encontrado' });
      return;
    }
    const bypassToken = getCourseBypassToken(preview.token);
    res.json({ bypassToken });
  } catch (error) {
    console.error('[getCourseBypass] Error:', error);
    res.status(500).json({ error: 'Error interno' });
  }
};

export const getRowBypass = async (req: Request, res: Response): Promise<void> => {
  try {
    const { rowId } = req.params;
    const row = await rowRepo().findOne({ where: { id: rowId } });
    if (!row) {
      res.status(404).json({ error: 'Clase no encontrada' });
      return;
    }
    const bypassToken = getBypassToken(row.id);
    res.json({ bypassToken });
  } catch (error) {
    console.error('[getRowBypass] Error:', error);
    res.status(500).json({ error: 'Error interno' });
  }
};